// @ts-check
/**
 * The 200-operation fixture (mission openapi-second-slice-01M6WXJ4, WP01/T001):
 * 50 paths x 4 methods = 200 operations, generated — never hand-edited — so
 * the seam suite's agent-index growth check (NFR-004) builds a spec whose
 * operation count no one would type by hand.
 *
 * The corpus deliberately includes:
 *  - operations with no `summary` (the llms.txt line falls back to operationId);
 *  - operations with no `operationId` (the slug and the llms.txt line fall back
 *    to `METHOD /path`);
 *  - two operations sharing one `operationId` (the renderer's duplicate-suffix
 *    slug rule, which the version switcher's same-operation mapping must follow).
 *
 * Run alone it writes the document to stdout (or to the file given as argv[2]);
 * the seam suite imports {@link ops200Yaml} and passes the text as a site file.
 */
import { writeFileSync } from 'node:fs';

/** The methods cycled over each path; uppercase as FR-023 orders them. */
const METHODS = ['get', 'put', 'post', 'delete'];

/**
 * @param {number} index
 * @param {string} method
 */
function operation(index, method) {
  const op = {};
  // Every 10th operation has no summary; every 7th has no operationId. Indexes
  // 27 (delete /thing-6) and 127 (delete /thing-31) collide on `sharedThing`.
  if (index % 10 !== 3) op.summary = `${method} thing ${index}`;
  if (index % 7 !== 5) op.operationId = index === 27 || index === 127 ? 'sharedThing' : `${method}Thing${index}`;
  op.responses = { '200': { description: `Thing ${index}.` } };
  return op;
}

/** The generated 200-operation document, as YAML text. */
export function ops200Yaml() {
  const lines = [
    'openapi: 3.1.0',
    'info:',
    '  title: Two hundred operations API',
    '  version: 1.0.0',
    '  description: Generated by ops-200/generate.mjs; 50 paths x 4 methods, some operations without summary or operationId and two duplicate operationIds.',
    'servers:',
    '  - url: https://api.example.test/v1',
    'paths:',
  ];
  let index = 0;
  for (let path = 0; path < 50; path += 1) {
    lines.push(`  /thing-${path}:`);
    for (const method of METHODS) {
      lines.push(`    ${method}:`);
      for (const [key, value] of Object.entries(operation(index, method))) {
        lines.push(`      ${key}: ${JSON.stringify(value)}`); // JSON is YAML
      }
      index += 1;
    }
  }
  return `${lines.join('\n')}\n`;
}

if (process.argv[1] && process.argv[1].endsWith('generate.mjs')) {
  const out = ops200Yaml();
  if (process.argv[2]) writeFileSync(process.argv[2], out);
  else process.stdout.write(out);
}
